cd /app && gcc -O3 -fPIC -shared -fcx-limited-range -fno-math-errno $(python3-config --includes) -I$(python -c "import numpy;print(numpy.get_include())") _eigen_fast.c -o _eigen_fast$(python3-config --extension-suffix) -lm && python - <<'EOF'
import numpy as np, _eigen_fast as E
np.random.seed(3)
stats={}
for t in range(4000):
    n=np.random.randint(2,11); typ=t%5
    if typ==0: A=np.eye(n,k=1)+np.random.choice([0.,1.,-2.])*np.eye(n)
    elif typ==1: A=np.round(np.random.normal(size=(n,n)))
    elif typ==2:
        J=np.eye(n,k=1)+2*np.eye(n); Q=np.linalg.qr(np.random.normal(size=(n,n)))[0]; A=Q@J@Q.T
    elif typ==3: A=np.eye(n,k=-1)
    else: A=np.random.normal(size=(n,n))
    r=E.dominant(A)
    key=typ
    stats.setdefault(key,[0,0,0])
    if r is None: stats[key][1]+=1; continue
    l,v=r
    if np.allclose(A@v,l*v): stats[key][0]+=1
    else: stats[key][2]+=1; print("RESID BAD",typ,n)
print("typ: ok, fallback, bad ->", stats)
EOF

