{"type": "text", "text": "/* Fast dominant eigenpair for small real matrices (n <= 32).
 *
 * Algorithm: Householder reduction to upper Hessenberg form, complex
 * single-shift (Wilkinson) QR iteration for the eigenvalues, then inverse
 * iteration with a pivoted LU factorization of (A - lambda I) for the
 * eigenvector.  The result is validated against a strict elementwise
 * residual test; on any failure the module returns None so that the Python
 * caller can fall back to numpy.linalg.eig.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>
#include <math.h>
#include <complex.h>

#define MAXN 32
typedef double complex cplx;
static const double EPS = 2.220446049250313e-16;

/* ---- Householder reduction to upper Hessenberg (in place, row major) ---- */
static void hessenberg(double *a, int n)
{
    double v[MAXN];
    int k, i, j;
    for (k = 0; k + 2 < n; k++) {
        double nrm = 0.0, vn2 = 0.0, alpha, beta, s;
        for (i = k + 1; i < n; i++) nrm += a[i * n + k] * a[i * n + k];
        if (nrm == 0.0) continue;
        alpha = sqrt(nrm);
        if (a[(k + 1) * n + k] > 0.0) alpha = -alpha;
        for (i = k + 1; i < n; i++) v[i] = a[i * n + k];
        v[k + 1] -= alpha;
        for (i = k + 1; i < n; i++) vn2 += v[i] * v[i];
        if (vn2 == 0.0) continue;
        beta = 2.0 / vn2;
        for (j = k; j < n; j++) {          /* A <- (I - beta v v^T) A */
            s = 0.0;
            for (i = k + 1; i < n; i++) s += v[i] * a[i * n + j];
            s *= beta;
            for (i = k + 1; i < n; i++) a[i * n + j] -= s * v[i];
        }
        for (i = 0; i < n; i++) {          /* A <- A (I - beta v v^T) */
            s = 0.0;
            for (j = k + 1; j < n; j++) s += a[i * n + j] * v[j];
            s *= beta;
            for (j = k + 1; j < n; j++) a[i * n + j] -= s * v[j];
        }
        a[(k + 1) * n + k] = alpha;
        for (i = k + 2; i < n; i++) a[i * n + k] = 0.0;
    }
}

/* ---- complex shifted QR iteration on an upper Hessenberg matrix ---- */
static int qr_eigvals(cplx *h, int n, cplx *w)
{
    int hi = n - 1, iter = 0, total = 0;
    cplx cs[MAXN], sn[MAXN];

    while (hi >= 0) {
        int lo, i, j;
        cplx shift, a, b, c, d, tr, det, disc, l1, l2;

        if (hi == 0) { w[0] = h[0]; break; }

        if (cabs(h[hi * n + hi - 1]) <=
            EPS * (cabs(h[(hi - 1) * n + hi - 1]) + cabs(h[hi * n + hi]))) {
            h[hi * n + hi - 1] = 0.0;
            w[hi] = h[hi * n + hi];
            hi--; iter = 0;
            continue;
        }
        if (++total > 60 * n + 200) return -1;

        lo = hi - 1;
        while (lo > 0) {
            if (cabs(h[lo * n + lo - 1]) <=
                EPS * (cabs(h[(lo - 1) * n + lo - 1]) + cabs(h[lo * n + lo]))) {
                h[lo * n + lo - 1] = 0.0;
                break;
            }
            lo--;
        }

        iter++;
        a = h[(hi - 1) * n + hi - 1];
        b = h[(hi - 1) * n + hi];
        c = h[hi * n + hi - 1];
        d = h[hi * n + hi];
        if (iter % 12 == 0) {
            shift = d + cabs(c);        /* exceptional shift */
        } else {
            tr = a + d;
            det = a * d - b * c;
            disc = csqrt(tr * tr - 4.0 * det);
            l1 = 0.5 * (tr + disc);
            l2 = 0.5 * (tr - disc);
            shift = (cabs(l1 - d) <= cabs(l2 - d)) ? l1 : l2;
        }
        if (!isfinite(creal(shift)) || !isfinite(cimag(shift))) return -1;

        for (i = lo; i <= hi; i++) h[i * n + i] -= shift;

        for (i = lo; i < hi; i++) {      /* QR of the shifted block */
            cplx f = h[i * n + i], g = h[(i + 1) * n + i], cc, ss, t1, t2;
            double r = sqrt(creal(f) * creal(f) + cimag(f) * cimag(f) +
                            creal(g) * creal(g) + cimag(g) * cimag(g));
            if (r == 0.0) { cs[i] = 1.0; sn[i] = 0.0; continue; }
            cc = f / r; ss = g / r;
            cs[i] = cc; sn[i] = ss;
            for (j = i; j <= hi; j++) {
                t1 = h[i * n + j];
                t2 = h[(i + 1) * n + j];
                h[i * n + j] = conj(cc) * t1 + conj(ss) * t2;
                h[(i + 1) * n + j] = -ss * t1 + cc * t2;
            }
        }
        for (i = lo; i < hi; i++) {      /* R * Q */
            cplx cc = cs[i], ss = sn[i], t1, t2;
            int imax = (i + 2 <= hi) ? i + 2 : hi;
            for (j = lo; j <= imax; j++) {
                t1 = h[j * n + i];
                t2 = h[j * n + i + 1];
                h[j * n + i] = cc * t1 + ss * t2;
                h[j * n + i + 1] = -conj(ss) * t1 + conj(cc) * t2;
            }
        }
        for (i = lo; i <= hi; i++) h[i * n + i] += shift;
    }
    return 0;
}

/* ---- LU with partial pivoting, tiny pivots perturbed ---- */
static void lu_decomp(cplx *m, int n, int *piv, double tol)
{
    int k, i, j;
    for (k = 0; k < n; k++) {
        int p = k;
        double best = cabs(m[k * n + k]), t;
        for (i = k + 1; i < n; i++) {
            t = cabs(m[i * n + k]);
            if (t > best) { best = t; p = i; }
        }
        piv[k] = p;
        if (p != k)
            for (j = 0; j < n; j++) {
                cplx tmp = m[k * n + j];
                m[k * n + j] = m[p * n + j];
                m[p * n + j] = tmp;
            }
        if (cabs(m[k * n + k]) <= tol) m[k * n + k] = tol;
        for (i = k + 1; i < n; i++) {
            cplx f = m[i * n + k] / m[k * n + k];
            m[i * n + k] = f;
            if (f != 0.0)
                for (j = k + 1; j < n; j++) m[i * n + j] -= f * m[k * n + j];
        }
    }
}

static void lu_solve(const cplx *m, int n, const int *piv, cplx *b)
{
    int i, j;
    for (i = 0; i < n; i++) {
        int p = piv[i];
        if (p != i) { cplx t = b[i]; b[i] = b[p]; b[p] = t; }
    }
    for (i = 1; i < n; i++)
        for (j = 0; j < i; j++) b[i] -= m[i * n + j] * b[j];
    for (i = n - 1; i >= 0; i--) {
        for (j = i + 1; j < n; j++) b[i] -= m[i * n + j] * b[j];
        b[i] /= m[i * n + i];
        if (cabs(b[i]) > 1e100) {       /* keep direction, avoid overflow */
            for (j = i; j < n; j++) b[j] *= 1e-100;
        }
    }
}

/* strict elementwise check of A v == lambda v (tighter than np.allclose) */
static double resid_norm(const double *a, int n, cplx lam, const cplx *v)
{
    int i, j;
    double t = 0.0;
    for (i = 0; i < n; i++) {
        cplx s = -lam * v[i];
        for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
        t += creal(s) * creal(s) + cimag(s) * cimag(s);
    }
    return sqrt(t);
}

static int residual_ok(const double *a, int n, cplx lam, const cplx *v)
{
    int i, j;
    for (i = 0; i < n; i++) {
        cplx s = 0.0, rhs = lam * v[i];
        for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
        if (!(cabs(s - rhs) <= 1e-9 + 1e-6 * cabs(rhs))) return 0;
    }
    return 1;
}

static int residual_ok_real(const double *a, int n, double lam, const double *v)
{
    int i, j;
    for (i = 0; i < n; i++) {
        double s = 0.0, rhs = lam * v[i];
        for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
        if (!(fabs(s - rhs) <= 1e-9 + 1e-6 * fabs(rhs))) return 0;
    }
    return 1;
}

static PyObject *make_result(cplx lam, const cplx *v, int n, int real_out,
                            const double *vr)
{
    PyObject *arr, *sc, *tup;
    npy_intp dims[1];
    PyArray_Descr *descr;
    dims[0] = n;

    if (real_out) {
        double lr = creal(lam);
        arr = PyArray_SimpleNew(1, dims, NPY_DOUBLE);
        if (!arr) return NULL;
        memcpy(PyArray_DATA((PyArrayObject *)arr), vr, (size_t)n * sizeof(double));
        descr = PyArray_DescrFromType(NPY_DOUBLE);
        if (!descr) { Py_DECREF(arr); return NULL; }
        sc = PyArray_Scalar(&lr, descr, NULL);
        Py_DECREF(descr);
    } else {
        npy_complex128 lc;
        arr = PyArray_SimpleNew(1, dims, NPY_COMPLEX128);
        if (!arr) return NULL;
        memcpy(PyArray_DATA((PyArrayObject *)arr), v, (size_t)n * sizeof(cplx));
        memcpy(&lc, &lam, sizeof(lc));
        descr = PyArray_DescrFromType(NPY_COMPLEX128);
        if (!descr) { Py_DECREF(arr); return NULL; }
        sc = PyArray_Scalar(&lc, descr, NULL);
        Py_DECREF(descr);
    }
    if (!sc) { Py_DECREF(arr); return NULL; }
    tup = PyTuple_Pack(2, sc, arr);
    Py_DECREF(sc);
    Py_DECREF(arr);
    return tup;
}

static PyObject *dominant(PyObject *self, PyObject *obj)
{
    PyArrayObject *ap;
    double a[MAXN * MAXN], hr[MAXN * MAXN];
    cplx h[MAXN * MAXN], m[MAXN * MAXN], w[MAXN], v[MAXN], bv[MAXN], lam;
    double vr[MAXN];
    int piv[MAXN];
    int n, i, j, it, imax;
    double anorm = 0.0, tol, maxabs, nv, bestr;
    npy_intp s0, s1;
    const char *base;

    if (!PyArray_Check(obj)) Py_RETURN_NONE;
    ap = (PyArrayObject *)obj;
    if (PyArray_TYPE(ap) != NPY_DOUBLE || PyArray_NDIM(ap) != 2) Py_RETURN_NONE;
    if (PyArray_DIM(ap, 0) != PyArray_DIM(ap, 1)) Py_RETURN_NONE;
    n = (int)PyArray_DIM(ap, 0);
    if (n < 1 || n > MAXN) Py_RETURN_NONE;

    base = (const char *)PyArray_DATA(ap);
    s0 = PyArray_STRIDE(ap, 0);
    s1 = PyArray_STRIDE(ap, 1);
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++) {
            double x = *(const double *)(base + i * s0 + j * s1);
            if (!isfinite(x)) Py_RETURN_NONE;
            a[i * n + j] = x;
            if (fabs(x) > anorm) anorm = fabs(x);
        }

    if (n == 1) {
        vr[0] = 1.0;
        return make_result(a[0], NULL, 1, 1, vr);
    }

    memcpy(hr, a, (size_t)(n * n) * sizeof(double));
    hessenberg(hr, n);
    for (i = 0; i < n * n; i++) h[i] = hr[i];
    for (i = 0; i < n; i++)
        for (j = 0; j + 1 < i; j++) h[i * n + j] = 0.0;
    if (qr_eigvals(h, n, w) != 0) Py_RETURN_NONE;

    maxabs = -1.0;
    imax = 0;
    for (i = 0; i < n; i++) {
        double t;
        if (!isfinite(creal(w[i])) || !isfinite(cimag(w[i]))) Py_RETURN_NONE;
        t = cabs(w[i]);
        if (t > maxabs) { maxabs = t; imax = i; }
    }
    /* among (near) ties prefer the member with the largest imaginary part,
       matching LAPACK's ordering of complex conjugate pairs */
    for (i = 0; i < n; i++)
        if (cabs(w[i]) >= maxabs * (1.0 - 1e-9) &&
            cimag(w[i]) > cimag(w[imax]))
            imax = i;
    lam = w[imax];
    /* inverse iteration on A - lambda I, with Rayleigh-quotient refinement
       as a rescue path for (nearly) defective matrices */
    tol = EPS * (anorm > 0.0 ? anorm : 1.0);
    {
        cplx lam0 = lam;
        int attempt, accepted = 0;
        for (attempt = 0; attempt < 3 && !accepted; attempt++) {
            cplx num, den;
            for (i = 0; i < n; i++)
                for (j = 0; j < n; j++)
                    m[i * n + j] = (i == j) ? a[i * n + j] - lam : a[i * n + j];
            lu_decomp(m, n, piv, tol);

            for (i = 0; i < n; i++) v[i] = 1.0 / sqrt((double)n) + 0.001 * i;
            bestr = -1.0;
            for (it = 0; it < 2; it++) {
                double rn;
                lu_solve(m, n, piv, v);
                nv = 0.0;
                for (i = 0; i < n; i++)
                    nv += creal(v[i]) * creal(v[i]) + cimag(v[i]) * cimag(v[i]);
                nv = sqrt(nv);
                if (!(nv > 0.0) || !isfinite(nv)) Py_RETURN_NONE;
                for (i = 0; i < n; i++) v[i] /= nv;
                rn = resid_norm(a, n, lam, v);
                if (bestr < 0.0 || rn < bestr) {
                    bestr = rn;
                    memcpy(bv, v, (size_t)n * sizeof(cplx));
                }
            }
            memcpy(v, bv, (size_t)n * sizeof(cplx));
            if (residual_ok(a, n, lam, v)) { accepted = 1; break; }

            /* Rayleigh quotient (v is unit norm) */
            num = 0.0; den = 0.0;
            for (i = 0; i < n; i++) {
                cplx s = 0.0;
                for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
                num += conj(v[i]) * s;
                den += conj(v[i]) * v[i];
            }
            if (den == 0.0 || !isfinite(creal(num)) || !isfinite(cimag(num)))
                Py_RETURN_NONE;
            num /= den;
            if (!(cabs(num - lam0) <= 0.05 * (cabs(lam0) > 1.0 ? cabs(lam0) : 1.0)))
                Py_RETURN_NONE;
            lam = num;
            if (residual_ok(a, n, lam, v)) { accepted = 1; break; }
        }
        if (!accepted) Py_RETURN_NONE;
    }

    if (fabs(cimag(lam)) <= 1e-12 * (1.0 + cabs(lam))) {
        double n1 = 0.0, n2 = 0.0;
        for (i = 0; i < n; i++) { n1 += creal(v[i]) * creal(v[i]); n2 += cimag(v[i]) * cimag(v[i]); }
        if (n1 >= n2) {
            nv = sqrt(n1);
            for (i = 0; i < n; i++) vr[i] = creal(v[i]) / nv;
        } else {
            nv = sqrt(n2);
            for (i = 0; i < n; i++) vr[i] = cimag(v[i]) / nv;
        }
        if (nv > 0.0 && residual_ok_real(a, n, creal(lam), vr))
            return make_result(creal(lam), NULL, n, 1, vr);
    }

    return make_result(lam, v, n, 0, NULL);
    return make_result(lam, v, n, 0, NULL);
}

static PyMethodDef methods[] = {
    {"dominant", dominant, METH_O, "dominant eigenpair or None"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigen_fast", NULL, -1, methods,
    NULL, NULL, NULL, NULL
};

PyMODINIT_FUNC PyInit__eigen_fast(void)
{
    PyObject *m = PyModule_Create(&moduledef);
    if (!m) return NULL;
    import_array();
    return m;
}
"}

edits.new:
/* Fast dominant eigenpair for small real matrices (n <= 32).
 *
 * Algorithm: power-of-two scaling, Householder reduction to upper Hessenberg
 * form, complex single-shift (Wilkinson) QR iteration for the eigenvalues,
 * then inverse iteration with a pivoted LU factorization of (A - lambda I)
 * for the eigenvector, plus Rayleigh-quotient refinement as a rescue path.
 * The result is validated against a strict elementwise residual test; on any
 * failure the module returns None so that the Python caller can fall back to
 * numpy.linalg.eig.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>
#include <math.h>
#include <complex.h>

#define MAXN 32
typedef double complex cplx;
static const double EPS = 2.220446049250313e-16;

#if defined(__GNUC__) && !defined(__clang__)
#define CX(re, im) __builtin_complex((double)(re), (double)(im))
#elif defined(CMPLX)
#define CX(re, im) CMPLX((double)(re), (double)(im))
#else
#define CX(re, im) ((cplx)((double)(re) + _Complex_I * (double)(im)))
#endif

/* inline complex helpers: the libm calls (cabs, csqrt) and the libgcc
 * complex multiply/divide helpers dominate the runtime otherwise.  The
 * matrix is pre-scaled so that its largest entry is ~1, hence the naive
 * formulas cannot overflow. */
static inline double zabs2(cplx z)
{
    return creal(z) * creal(z) + cimag(z) * cimag(z);
}

static inline double zabs(cplx z) { return sqrt(zabs2(z)); }

static inline cplx zmul(cplx x, cplx y)
{
    double a = creal(x), b = cimag(x), c = creal(y), d = cimag(y);
    return CX(a * c - b * d, a * d + b * c);
}

static inline cplx zdiv(cplx x, cplx y)
{
    double a = creal(x), b = cimag(x), c = creal(y), d = cimag(y);
    double den = c * c + d * d;
    return CX((a * c + b * d) / den, (b * c - a * d) / den);
}

static inline cplx zsqrt(cplx z)
{
    double x = creal(z), y = cimag(z), r, t;
    if (x == 0.0 && y == 0.0) return CX(0.0, 0.0);
    r = zabs(z);
    if (x >= 0.0) {
        t = sqrt(0.5 * (r + x));
        return CX(t, 0.5 * y / t);
    }
    t = sqrt(0.5 * (r - x));
    return CX(0.5 * fabs(y) / t, y >= 0.0 ? t : -t);
}

/* ---- Householder reduction to upper Hessenberg (in place, row major) ---- */
static void hessenberg(double *a, int n)
{
    double v[MAXN];
    int k, i, j;
    for (k = 0; k + 2 < n; k++) {
        double nrm = 0.0, vn2 = 0.0, alpha, beta, s;
        for (i = k + 1; i < n; i++) nrm += a[i * n + k] * a[i * n + k];
        if (nrm == 0.0) continue;
        alpha = sqrt(nrm);
        if (a[(k + 1) * n + k] > 0.0) alpha = -alpha;
        for (i = k + 1; i < n; i++) v[i] = a[i * n + k];
        v[k + 1] -= alpha;
        for (i = k + 1; i < n; i++) vn2 += v[i] * v[i];
        if (vn2 == 0.0) continue;
        beta = 2.0 / vn2;
        for (j = k; j < n; j++) {          /* A <- (I - beta v v^T) A */
            s = 0.0;
            for (i = k + 1; i < n; i++) s += v[i] * a[i * n + j];
            s *= beta;
            for (i = k + 1; i < n; i++) a[i * n + j] -= s * v[i];
        }
        for (i = 0; i < n; i++) {          /* A <- A (I - beta v v^T) */
            s = 0.0;
            for (j = k + 1; j < n; j++) s += a[i * n + j] * v[j];
            s *= beta;
            for (j = k + 1; j < n; j++) a[i * n + j] -= s * v[j];
        }
        a[(k + 1) * n + k] = alpha;
        for (i = k + 2; i < n; i++) a[i * n + k] = 0.0;
    }
}

/* ---- complex shifted QR iteration on an upper Hessenberg matrix ---- */
static int qr_eigvals(cplx *h, int n, cplx *w)
{
    int hi = n - 1, iter = 0, total = 0;
    cplx cs[MAXN], sn[MAXN];

    while (hi >= 0) {
        int lo, i, j;
        cplx shift, a, b, c, d, tr, det, disc, l1, l2;

        if (hi == 0) { w[0] = h[0]; break; }

        if (zabs(h[hi * n + hi - 1]) <=
            EPS * (zabs(h[(hi - 1) * n + hi - 1]) + zabs(h[hi * n + hi]))) {
            h[hi * n + hi - 1] = CX(0.0, 0.0);
            w[hi] = h[hi * n + hi];
            hi--; iter = 0;
            continue;
        }
        if (++total > 60 * n + 200) return -1;

        lo = hi - 1;
        while (lo > 0) {
            if (zabs(h[lo * n + lo - 1]) <=
                EPS * (zabs(h[(lo - 1) * n + lo - 1]) + zabs(h[lo * n + lo]))) {
                h[lo * n + lo - 1] = CX(0.0, 0.0);
                break;
            }
            lo--;
        }

        iter++;
        a = h[(hi - 1) * n + hi - 1];
        b = h[(hi - 1) * n + hi];
        c = h[hi * n + hi - 1];
        d = h[hi * n + hi];
        if (iter % 12 == 0) {
            shift = d + zabs(c);        /* exceptional shift */
        } else {
            tr = a + d;
            det = zmul(a, d) - zmul(b, c);
            disc = zsqrt(zmul(tr, tr) - 4.0 * det);
            l1 = 0.5 * (tr + disc);
            l2 = 0.5 * (tr - disc);
            shift = (zabs2(l1 - d) <= zabs2(l2 - d)) ? l1 : l2;
        }
        if (!isfinite(creal(shift)) || !isfinite(cimag(shift))) return -1;

        for (i = lo; i <= hi; i++) h[i * n + i] -= shift;

        for (i = lo; i < hi; i++) {      /* QR of the shifted block */
            cplx f = h[i * n + i], g = h[(i + 1) * n + i], cc, ss, t1, t2;
            double r = sqrt(zabs2(f) + zabs2(g));
            if (r == 0.0) { cs[i] = CX(1.0, 0.0); sn[i] = CX(0.0, 0.0); continue; }
            cc = f / r; ss = g / r;
            cs[i] = cc; sn[i] = ss;
            for (j = i; j <= hi; j++) {
                t1 = h[i * n + j];
                t2 = h[(i + 1) * n + j];
                h[i * n + j] = zmul(conj(cc), t1) + zmul(conj(ss), t2);
                h[(i + 1) * n + j] = zmul(-ss, t1) + zmul(cc, t2);
            }
        }
        for (i = lo; i < hi; i++) {      /* R * Q */
            cplx cc = cs[i], ss = sn[i], t1, t2;
            int imax = (i + 2 <= hi) ? i + 2 : hi;
            for (j = lo; j <= imax; j++) {
                t1 = h[j * n + i];
                t2 = h[j * n + i + 1];
                h[j * n + i] = zmul(cc, t1) + zmul(ss, t2);
                h[j * n + i + 1] = zmul(-conj(ss), t1) + zmul(conj(cc), t2);
            }
        }
        for (i = lo; i <= hi; i++) h[i * n + i] += shift;
    }
    return 0;
}

/* ---- LU with partial pivoting, tiny pivots perturbed ---- */
static void lu_decomp(cplx *m, int n, int *piv, double tol)
{
    int k, i, j;
    double tol2 = tol * tol;
    for (k = 0; k < n; k++) {
        int p = k;
        double best = zabs2(m[k * n + k]), t;
        for (i = k + 1; i < n; i++) {
            t = zabs2(m[i * n + k]);
            if (t > best) { best = t; p = i; }
        }
        piv[k] = p;
        if (p != k)
            for (j = 0; j < n; j++) {
                cplx tmp = m[k * n + j];
                m[k * n + j] = m[p * n + j];
                m[p * n + j] = tmp;
            }
        if (zabs2(m[k * n + k]) <= tol2) m[k * n + k] = CX(tol, 0.0);
        for (i = k + 1; i < n; i++) {
            cplx f = zdiv(m[i * n + k], m[k * n + k]);
            m[i * n + k] = f;
            if (f != 0.0)
                for (j = k + 1; j < n; j++)
                    m[i * n + j] -= zmul(f, m[k * n + j]);
        }
    }
}

static void lu_solve(const cplx *m, int n, const int *piv, cplx *b)
{
    int i, j;
    for (i = 0; i < n; i++) {
        int p = piv[i];
        if (p != i) { cplx t = b[i]; b[i] = b[p]; b[p] = t; }
    }
    for (i = 1; i < n; i++)
        for (j = 0; j < i; j++) b[i] -= zmul(m[i * n + j], b[j]);
    for (i = n - 1; i >= 0; i--) {
        for (j = i + 1; j < n; j++) b[i] -= zmul(m[i * n + j], b[j]);
        b[i] = zdiv(b[i], m[i * n + i]);
        if (zabs2(b[i]) > 1e200) {      /* keep direction, avoid overflow */
            for (j = i; j < n; j++) b[j] *= 1e-100;
        }
    }
}

static double resid_norm(const double *a, int n, cplx lam, const cplx *v)
{
    int i, j;
    double t = 0.0;
    for (i = 0; i < n; i++) {
        cplx s = -zmul(lam, v[i]);
        for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
        t += zabs2(s);
    }
    return sqrt(t);
}

/* strict elementwise check of A v == lambda v (tighter than np.allclose) */
static int residual_ok(const double *a, int n, cplx lam, const cplx *v,
                       double atol)
{
    int i, j;
    for (i = 0; i < n; i++) {
        cplx s = CX(0.0, 0.0), rhs = zmul(lam, v[i]);
        for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
        if (!(zabs(s - rhs) <= atol + 1e-6 * zabs(rhs))) return 0;
    }
    return 1;
}

static int residual_ok_real(const double *a, int n, double lam, const double *v,
                           double atol)
{
    int i, j;
    for (i = 0; i < n; i++) {
        double s = 0.0, rhs = lam * v[i];
        for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
        if (!(fabs(s - rhs) <= atol + 1e-6 * fabs(rhs))) return 0;
    }
    return 1;
}

static PyObject *make_result(cplx lam, const cplx *v, int n, int real_out,
                            const double *vr)
{
    PyObject *arr, *sc, *tup;
    npy_intp dims[1];
    PyArray_Descr *descr;
    dims[0] = n;

    if (real_out) {
        double lr = creal(lam);
        arr = PyArray_SimpleNew(1, dims, NPY_DOUBLE);
        if (!arr) return NULL;
        memcpy(PyArray_DATA((PyArrayObject *)arr), vr, (size_t)n * sizeof(double));
        descr = PyArray_DescrFromType(NPY_DOUBLE);
        if (!descr) { Py_DECREF(arr); return NULL; }
        sc = PyArray_Scalar(&lr, descr, NULL);
        Py_DECREF(descr);
    } else {
        npy_complex128 lc;
        arr = PyArray_SimpleNew(1, dims, NPY_COMPLEX128);
        if (!arr) return NULL;
        memcpy(PyArray_DATA((PyArrayObject *)arr), v, (size_t)n * sizeof(cplx));
        memcpy(&lc, &lam, sizeof(lc));
        descr = PyArray_DescrFromType(NPY_COMPLEX128);
        if (!descr) { Py_DECREF(arr); return NULL; }
        sc = PyArray_Scalar(&lc, descr, NULL);
        Py_DECREF(descr);
    }
    if (!sc) { Py_DECREF(arr); return NULL; }
    tup = PyTuple_Pack(2, sc, arr);
    Py_DECREF(sc);
    Py_DECREF(arr);
    return tup;
}

static PyObject *dominant(PyObject *self, PyObject *obj)
{
    PyArrayObject *ap;
    double a[MAXN * MAXN], hr[MAXN * MAXN];
    cplx h[MAXN * MAXN], m[MAXN * MAXN], w[MAXN], v[MAXN], bv[MAXN], lam;
    double vr[MAXN];
    int piv[MAXN];
    int n, i, j, it, imax, expo;
    double anorm = 0.0, tol, maxabs, nv, bestr, scale, atol;
    npy_intp s0, s1;
    const char *base;

    if (!PyArray_Check(obj)) Py_RETURN_NONE;
    ap = (PyArrayObject *)obj;
    if (PyArray_TYPE(ap) != NPY_DOUBLE || PyArray_NDIM(ap) != 2) Py_RETURN_NONE;
    if (PyArray_DIM(ap, 0) != PyArray_DIM(ap, 1)) Py_RETURN_NONE;
    n = (int)PyArray_DIM(ap, 0);
    if (n < 1 || n > MAXN) Py_RETURN_NONE;

    base = (const char *)PyArray_DATA(ap);
    s0 = PyArray_STRIDE(ap, 0);
    s1 = PyArray_STRIDE(ap, 1);
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++) {
            double x = *(const double *)(base + i * s0 + j * s1);
            if (!isfinite(x)) Py_RETURN_NONE;
            a[i * n + j] = x;
            if (fabs(x) > anorm) anorm = fabs(x);
        }

    /* exact power-of-two scaling so that max|a_ij| is in [0.5, 1) */
    scale = 1.0;
    if (anorm > 0.0) {
        (void)frexp(anorm, &expo);
        if (expo != 0) {
            scale = ldexp(1.0, -expo);
            if (!isfinite(scale) || scale == 0.0) Py_RETURN_NONE;
            for (i = 0; i < n * n; i++) a[i] *= scale;
            anorm *= scale;
        }
    }
    /* np.allclose uses atol=1e-8 on the unscaled problem; use 1e-9 with the
       scaling folded in for margin */
    atol = 1e-9 * scale;

    if (n == 1) {
        vr[0] = 1.0;
        return make_result(CX(a[0] / scale, 0.0), NULL, 1, 1, vr);
    }

    memcpy(hr, a, (size_t)(n * n) * sizeof(double));
    hessenberg(hr, n);
    for (i = 0; i < n * n; i++) h[i] = CX(hr[i], 0.0);
    for (i = 0; i < n; i++)
        for (j = 0; j + 1 < i; j++) h[i * n + j] = CX(0.0, 0.0);
    if (qr_eigvals(h, n, w) != 0) Py_RETURN_NONE;

    maxabs = -1.0;
    imax = 0;
    for (i = 0; i < n; i++) {
        double t;
        if (!isfinite(creal(w[i])) || !isfinite(cimag(w[i]))) Py_RETURN_NONE;
        t = zabs2(w[i]);
        if (t > maxabs) { maxabs = t; imax = i; }
    }
    /* among (near) ties prefer the member with the largest imaginary part,
       matching LAPACK's ordering of complex conjugate pairs */
    for (i = 0; i < n; i++)
        if (zabs2(w[i]) >= maxabs * (1.0 - 1e-9) &&
            cimag(w[i]) > cimag(w[imax]))
            imax = i;
    lam = w[imax];

    /* inverse iteration on A - lambda I, with Rayleigh-quotient refinement
       as a rescue path for (nearly) defective matrices */
    tol = EPS * (anorm > 0.0 ? anorm : 1.0);
    {
        cplx lam0 = lam;
        int attempt, accepted = 0;
        for (attempt = 0; attempt < 3 && !accepted; attempt++) {
            cplx num, den;
            for (i = 0; i < n; i++)
                for (j = 0; j < n; j++)
                    m[i * n + j] = (i == j) ? a[i * n + j] - lam
                                            : CX(a[i * n + j], 0.0);
            lu_decomp(m, n, piv, tol);

            for (i = 0; i < n; i++) v[i] = CX(1.0 / sqrt((double)n) + 0.001 * i, 0.0);
            bestr = -1.0;
            for (it = 0; it < 2; it++) {
                double rn;
                lu_solve(m, n, piv, v);
                nv = 0.0;
                for (i = 0; i < n; i++) nv += zabs2(v[i]);
                nv = sqrt(nv);
                if (!(nv > 0.0) || !isfinite(nv)) Py_RETURN_NONE;
                for (i = 0; i < n; i++) v[i] /= nv;
                rn = resid_norm(a, n, lam, v);
                if (bestr < 0.0 || rn < bestr) {
                    bestr = rn;
                    memcpy(bv, v, (size_t)n * sizeof(cplx));
                }
            }
            memcpy(v, bv, (size_t)n * sizeof(cplx));
            if (residual_ok(a, n, lam, v, atol)) { accepted = 1; break; }

            /* Rayleigh quotient (v is unit norm) */
            num = CX(0.0, 0.0); den = CX(0.0, 0.0);
            for (i = 0; i < n; i++) {
                cplx s = CX(0.0, 0.0);
                for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
                num += zmul(conj(v[i]), s);
                den += zmul(conj(v[i]), v[i]);
            }
            if (den == 0.0 || !isfinite(creal(num)) || !isfinite(cimag(num)))
                Py_RETURN_NONE;
            num = zdiv(num, den);
            if (!(zabs(num - lam0) <= 0.05 * (zabs(lam0) > 1.0 ? zabs(lam0) : 1.0)))
                Py_RETURN_NONE;
            lam = num;
            if (residual_ok(a, n, lam, v, atol)) { accepted = 1; break; }
        }
        if (!accepted) Py_RETURN_NONE;
    }

    if (fabs(cimag(lam)) <= 1e-12 * (1.0 + zabs(lam))) {
        double n1 = 0.0, n2 = 0.0;
        for (i = 0; i < n; i++) {
            n1 += creal(v[i]) * creal(v[i]);
            n2 += cimag(v[i]) * cimag(v[i]);
        }
        if (n1 >= n2) {
            nv = sqrt(n1);
            for (i = 0; i < n; i++) vr[i] = creal(v[i]) / nv;
        } else {
            nv = sqrt(n2);
            for (i = 0; i < n; i++) vr[i] = cimag(v[i]) / nv;
        }
        if (nv > 0.0 && residual_ok_real(a, n, creal(lam), vr, atol))
            return make_result(CX(creal(lam) / scale, 0.0), NULL, n, 1, vr);
    }

    return make_result(zdiv(lam, CX(scale, 0.0)), v, n, 0, NULL);
}

static PyMethodDef methods[] = {
    {"dominant", dominant, METH_O, "dominant eigenpair or None"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigen_fast", NULL, -1, methods,
    NULL, NULL, NULL, NULL
};

PyMODINIT_FUNC PyInit__eigen_fast(void)
{
    PyObject *m = PyModule_Create(&moduledef);
    if (!m) return NULL;
    import_array();
    return m;
}

/* Fast dominant eigenpair for small real matrices (n <= 32).
 *
 * Algorithm: power-of-two scaling, Householder reduction to upper Hessenberg
 * form, complex single-shift (Wilkinson) QR iteration for the eigenvalues,
 * then inverse iteration with a pivoted LU factorization of (A - lambda I)
 * for the eigenvector, plus Rayleigh-quotient refinement as a rescue path.
 * The result is validated against a strict elementwise residual test; on any
 * failure the module returns None so that the Python caller can fall back to
 * numpy.linalg.eig.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <numpy/arrayobject.h>
#include <math.h>
#include <complex.h>

#define MAXN 32
typedef double complex cplx;
static const double EPS = 2.220446049250313e-16;

#if defined(__GNUC__) && !defined(__clang__)
#define CX(re, im) __builtin_complex((double)(re), (double)(im))
#elif defined(CMPLX)
#define CX(re, im) CMPLX((double)(re), (double)(im))
#else
#define CX(re, im) ((cplx)((double)(re) + _Complex_I * (double)(im)))
#endif

/* inline complex helpers: the libm calls (cabs, csqrt) and the libgcc
 * complex multiply/divide helpers dominate the runtime otherwise.  The
 * matrix is pre-scaled so that its largest entry is ~1, hence the naive
 * formulas cannot overflow. */
static inline double zabs2(cplx z)
{
    return creal(z) * creal(z) + cimag(z) * cimag(z);
}

static inline double zabs(cplx z) { return sqrt(zabs2(z)); }

static inline cplx zmul(cplx x, cplx y)
{
    double a = creal(x), b = cimag(x), c = creal(y), d = cimag(y);
    return CX(a * c - b * d, a * d + b * c);
}

static inline cplx zdiv(cplx x, cplx y)
{
    double a = creal(x), b = cimag(x), c = creal(y), d = cimag(y);
    double den = c * c + d * d;
    return CX((a * c + b * d) / den, (b * c - a * d) / den);
}

static inline cplx zsqrt(cplx z)
{
    double x = creal(z), y = cimag(z), r, t;
    if (x == 0.0 && y == 0.0) return CX(0.0, 0.0);
    r = zabs(z);
    if (x >= 0.0) {
        t = sqrt(0.5 * (r + x));
        return CX(t, 0.5 * y / t);
    }
    t = sqrt(0.5 * (r - x));
    return CX(0.5 * fabs(y) / t, y >= 0.0 ? t : -t);
}

/* ---- Householder reduction to upper Hessenberg (in place, row major) ---- */
static void hessenberg(double *a, int n)
{
    double v[MAXN];
    int k, i, j;
    for (k = 0; k + 2 < n; k++) {
        double nrm = 0.0, vn2 = 0.0, alpha, beta, s;
        for (i = k + 1; i < n; i++) nrm += a[i * n + k] * a[i * n + k];
        if (nrm == 0.0) continue;
        alpha = sqrt(nrm);
        if (a[(k + 1) * n + k] > 0.0) alpha = -alpha;
        for (i = k + 1; i < n; i++) v[i] = a[i * n + k];
        v[k + 1] -= alpha;
        for (i = k + 1; i < n; i++) vn2 += v[i] * v[i];
        if (vn2 == 0.0) continue;
        beta = 2.0 / vn2;
        for (j = k; j < n; j++) {          /* A <- (I - beta v v^T) A */
            s = 0.0;
            for (i = k + 1; i < n; i++) s += v[i] * a[i * n + j];
            s *= beta;
            for (i = k + 1; i < n; i++) a[i * n + j] -= s * v[i];
        }
        for (i = 0; i < n; i++) {          /* A <- A (I - beta v v^T) */
            s = 0.0;
            for (j = k + 1; j < n; j++) s += a[i * n + j] * v[j];
            s *= beta;
            for (j = k + 1; j < n; j++) a[i * n + j] -= s * v[j];
        }
        a[(k + 1) * n + k] = alpha;
        for (i = k + 2; i < n; i++) a[i * n + k] = 0.0;
    }
}

/* ---- complex shifted QR iteration on an upper Hessenberg matrix ---- */
static int qr_eigvals(cplx *h, int n, cplx *w)
{
    int hi = n - 1, iter = 0, total = 0;
    cplx cs[MAXN], sn[MAXN];

    while (hi >= 0) {
        int lo, i, j;
        cplx shift, a, b, c, d, tr, det, disc, l1, l2;

        if (hi == 0) { w[0] = h[0]; break; }

        if (zabs(h[hi * n + hi - 1]) <=
            EPS * (zabs(h[(hi - 1) * n + hi - 1]) + zabs(h[hi * n + hi]))) {
            h[hi * n + hi - 1] = CX(0.0, 0.0);
            w[hi] = h[hi * n + hi];
            hi--; iter = 0;
            continue;
        }
        if (++total > 60 * n + 200) return -1;

        lo = hi - 1;
        while (lo > 0) {
            if (zabs(h[lo * n + lo - 1]) <=
                EPS * (zabs(h[(lo - 1) * n + lo - 1]) + zabs(h[lo * n + lo]))) {
                h[lo * n + lo - 1] = CX(0.0, 0.0);
                break;
            }
            lo--;
        }

        iter++;
        a = h[(hi - 1) * n + hi - 1];
        b = h[(hi - 1) * n + hi];
        c = h[hi * n + hi - 1];
        d = h[hi * n + hi];
        if (iter % 12 == 0) {
            shift = d + zabs(c);        /* exceptional shift */
        } else {
            tr = a + d;
            det = zmul(a, d) - zmul(b, c);
            disc = zsqrt(zmul(tr, tr) - 4.0 * det);
            l1 = 0.5 * (tr + disc);
            l2 = 0.5 * (tr - disc);
            shift = (zabs2(l1 - d) <= zabs2(l2 - d)) ? l1 : l2;
        }
        if (!isfinite(creal(shift)) || !isfinite(cimag(shift))) return -1;

        for (i = lo; i <= hi; i++) h[i * n + i] -= shift;

        for (i = lo; i < hi; i++) {      /* QR of the shifted block */
            cplx f = h[i * n + i], g = h[(i + 1) * n + i], cc, ss, t1, t2;
            double r = sqrt(zabs2(f) + zabs2(g));
            if (r == 0.0) { cs[i] = CX(1.0, 0.0); sn[i] = CX(0.0, 0.0); continue; }
            cc = f / r; ss = g / r;
            cs[i] = cc; sn[i] = ss;
            for (j = i; j <= hi; j++) {
                t1 = h[i * n + j];
                t2 = h[(i + 1) * n + j];
                h[i * n + j] = zmul(conj(cc), t1) + zmul(conj(ss), t2);
                h[(i + 1) * n + j] = zmul(-ss, t1) + zmul(cc, t2);
            }
        }
        for (i = lo; i < hi; i++) {      /* R * Q */
            cplx cc = cs[i], ss = sn[i], t1, t2;
            int imax = (i + 2 <= hi) ? i + 2 : hi;
            for (j = lo; j <= imax; j++) {
                t1 = h[j * n + i];
                t2 = h[j * n + i + 1];
                h[j * n + i] = zmul(cc, t1) + zmul(ss, t2);
                h[j * n + i + 1] = zmul(-conj(ss), t1) + zmul(conj(cc), t2);
            }
        }
        for (i = lo; i <= hi; i++) h[i * n + i] += shift;
    }
    return 0;
}

/* ---- LU with partial pivoting, tiny pivots perturbed ---- */
static void lu_decomp(cplx *m, int n, int *piv, double tol)
{
    int k, i, j;
    double tol2 = tol * tol;
    for (k = 0; k < n; k++) {
        int p = k;
        double best = zabs2(m[k * n + k]), t;
        for (i = k + 1; i < n; i++) {
            t = zabs2(m[i * n + k]);
            if (t > best) { best = t; p = i; }
        }
        piv[k] = p;
        if (p != k)
            for (j = 0; j < n; j++) {
                cplx tmp = m[k * n + j];
                m[k * n + j] = m[p * n + j];
                m[p * n + j] = tmp;
            }
        if (zabs2(m[k * n + k]) <= tol2) m[k * n + k] = CX(tol, 0.0);
        for (i = k + 1; i < n; i++) {
            cplx f = zdiv(m[i * n + k], m[k * n + k]);
            m[i * n + k] = f;
            if (f != 0.0)
                for (j = k + 1; j < n; j++)
                    m[i * n + j] -= zmul(f, m[k * n + j]);
        }
    }
}

static void lu_solve(const cplx *m, int n, const int *piv, cplx *b)
{
    int i, j;
    for (i = 0; i < n; i++) {
        int p = piv[i];
        if (p != i) { cplx t = b[i]; b[i] = b[p]; b[p] = t; }
    }
    for (i = 1; i < n; i++)
        for (j = 0; j < i; j++) b[i] -= zmul(m[i * n + j], b[j]);
    for (i = n - 1; i >= 0; i--) {
        for (j = i + 1; j < n; j++) b[i] -= zmul(m[i * n + j], b[j]);
        b[i] = zdiv(b[i], m[i * n + i]);
        if (zabs2(b[i]) > 1e200) {      /* keep direction, avoid overflow */
            for (j = i; j < n; j++) b[j] *= 1e-100;
        }
    }
}

static double resid_norm(const double *a, int n, cplx lam, const cplx *v)
{
    int i, j;
    double t = 0.0;
    for (i = 0; i < n; i++) {
        cplx s = -zmul(lam, v[i]);
        for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
        t += zabs2(s);
    }
    return sqrt(t);
}

/* strict elementwise check of A v == lambda v (tighter than np.allclose) */
static int residual_ok(const double *a, int n, cplx lam, const cplx *v,
                       double atol)
{
    int i, j;
    for (i = 0; i < n; i++) {
        cplx s = CX(0.0, 0.0), rhs = zmul(lam, v[i]);
        for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
        if (!(zabs(s - rhs) <= atol + 1e-6 * zabs(rhs))) return 0;
    }
    return 1;
}

static int residual_ok_real(const double *a, int n, double lam, const double *v,
                           double atol)
{
    int i, j;
    for (i = 0; i < n; i++) {
        double s = 0.0, rhs = lam * v[i];
        for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
        if (!(fabs(s - rhs) <= atol + 1e-6 * fabs(rhs))) return 0;
    }
    return 1;
}

static PyObject *make_result(cplx lam, const cplx *v, int n, int real_out,
                            const double *vr)
{
    PyObject *arr, *sc, *tup;
    npy_intp dims[1];
    PyArray_Descr *descr;
    dims[0] = n;

    if (real_out) {
        double lr = creal(lam);
        arr = PyArray_SimpleNew(1, dims, NPY_DOUBLE);
        if (!arr) return NULL;
        memcpy(PyArray_DATA((PyArrayObject *)arr), vr, (size_t)n * sizeof(double));
        descr = PyArray_DescrFromType(NPY_DOUBLE);
        if (!descr) { Py_DECREF(arr); return NULL; }
        sc = PyArray_Scalar(&lr, descr, NULL);
        Py_DECREF(descr);
    } else {
        npy_complex128 lc;
        arr = PyArray_SimpleNew(1, dims, NPY_COMPLEX128);
        if (!arr) return NULL;
        memcpy(PyArray_DATA((PyArrayObject *)arr), v, (size_t)n * sizeof(cplx));
        memcpy(&lc, &lam, sizeof(lc));
        descr = PyArray_DescrFromType(NPY_COMPLEX128);
        if (!descr) { Py_DECREF(arr); return NULL; }
        sc = PyArray_Scalar(&lc, descr, NULL);
        Py_DECREF(descr);
    }
    if (!sc) { Py_DECREF(arr); return NULL; }
    tup = PyTuple_Pack(2, sc, arr);
    Py_DECREF(sc);
    Py_DECREF(arr);
    return tup;
}

static PyObject *dominant(PyObject *self, PyObject *obj)
{
    PyArrayObject *ap;
    double a[MAXN * MAXN], hr[MAXN * MAXN];
    cplx h[MAXN * MAXN], m[MAXN * MAXN], w[MAXN], v[MAXN], bv[MAXN], lam;
    double vr[MAXN];
    int piv[MAXN];
    int n, i, j, it, imax, expo;
    double anorm = 0.0, tol, maxabs, nv, bestr, scale, atol;
    npy_intp s0, s1;
    const char *base;

    if (!PyArray_Check(obj)) Py_RETURN_NONE;
    ap = (PyArrayObject *)obj;
    if (PyArray_TYPE(ap) != NPY_DOUBLE || PyArray_NDIM(ap) != 2) Py_RETURN_NONE;
    if (PyArray_DIM(ap, 0) != PyArray_DIM(ap, 1)) Py_RETURN_NONE;
    n = (int)PyArray_DIM(ap, 0);
    if (n < 1 || n > MAXN) Py_RETURN_NONE;

    base = (const char *)PyArray_DATA(ap);
    s0 = PyArray_STRIDE(ap, 0);
    s1 = PyArray_STRIDE(ap, 1);
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++) {
            double x = *(const double *)(base + i * s0 + j * s1);
            if (!isfinite(x)) Py_RETURN_NONE;
            a[i * n + j] = x;
            if (fabs(x) > anorm) anorm = fabs(x);
        }

    /* exact power-of-two scaling so that max|a_ij| is in [0.5, 1) */
    scale = 1.0;
    if (anorm > 0.0) {
        (void)frexp(anorm, &expo);
        if (expo != 0) {
            scale = ldexp(1.0, -expo);
            if (!isfinite(scale) || scale == 0.0) Py_RETURN_NONE;
            for (i = 0; i < n * n; i++) a[i] *= scale;
            anorm *= scale;
        }
    }
    /* np.allclose uses atol=1e-8 on the unscaled problem; use 1e-9 with the
       scaling folded in for margin */
    atol = 1e-9 * scale;

    if (n == 1) {
        vr[0] = 1.0;
        return make_result(CX(a[0] / scale, 0.0), NULL, 1, 1, vr);
    }

    memcpy(hr, a, (size_t)(n * n) * sizeof(double));
    hessenberg(hr, n);
    for (i = 0; i < n * n; i++) h[i] = CX(hr[i], 0.0);
    for (i = 0; i < n; i++)
        for (j = 0; j + 1 < i; j++) h[i * n + j] = CX(0.0, 0.0);
    if (qr_eigvals(h, n, w) != 0) Py_RETURN_NONE;

    maxabs = -1.0;
    imax = 0;
    for (i = 0; i < n; i++) {
        double t;
        if (!isfinite(creal(w[i])) || !isfinite(cimag(w[i]))) Py_RETURN_NONE;
        t = zabs2(w[i]);
        if (t > maxabs) { maxabs = t; imax = i; }
    }
    /* among (near) ties prefer the member with the largest imaginary part,
       matching LAPACK's ordering of complex conjugate pairs */
    for (i = 0; i < n; i++)
        if (zabs2(w[i]) >= maxabs * (1.0 - 1e-9) &&
            cimag(w[i]) > cimag(w[imax]))
            imax = i;
    lam = w[imax];

    /* inverse iteration on A - lambda I, with Rayleigh-quotient refinement
       as a rescue path for (nearly) defective matrices */
    tol = EPS * (anorm > 0.0 ? anorm : 1.0);
    {
        cplx lam0 = lam;
        int attempt, accepted = 0;
        for (attempt = 0; attempt < 3 && !accepted; attempt++) {
            cplx num, den;
            for (i = 0; i < n; i++)
                for (j = 0; j < n; j++)
                    m[i * n + j] = (i == j) ? a[i * n + j] - lam
                                            : CX(a[i * n + j], 0.0);
            lu_decomp(m, n, piv, tol);

            for (i = 0; i < n; i++) v[i] = CX(1.0 / sqrt((double)n) + 0.001 * i, 0.0);
            bestr = -1.0;
            for (it = 0; it < 2; it++) {
                double rn;
                lu_solve(m, n, piv, v);
                nv = 0.0;
                for (i = 0; i < n; i++) nv += zabs2(v[i]);
                nv = sqrt(nv);
                if (!(nv > 0.0) || !isfinite(nv)) Py_RETURN_NONE;
                for (i = 0; i < n; i++) v[i] /= nv;
                rn = resid_norm(a, n, lam, v);
                if (bestr < 0.0 || rn < bestr) {
                    bestr = rn;
                    memcpy(bv, v, (size_t)n * sizeof(cplx));
                }
            }
            memcpy(v, bv, (size_t)n * sizeof(cplx));
            if (residual_ok(a, n, lam, v, atol)) { accepted = 1; break; }

            /* Rayleigh quotient (v is unit norm) */
            num = CX(0.0, 0.0); den = CX(0.0, 0.0);
            for (i = 0; i < n; i++) {
                cplx s = CX(0.0, 0.0);
                for (j = 0; j < n; j++) s += a[i * n + j] * v[j];
                num += zmul(conj(v[i]), s);
                den += zmul(conj(v[i]), v[i]);
            }
            if (den == 0.0 || !isfinite(creal(num)) || !isfinite(cimag(num)))
                Py_RETURN_NONE;
            num = zdiv(num, den);
            if (!(zabs(num - lam0) <= 0.05 * (zabs(lam0) > 1.0 ? zabs(lam0) : 1.0)))
                Py_RETURN_NONE;
            lam = num;
            if (residual_ok(a, n, lam, v, atol)) { accepted = 1; break; }
        }
        if (!accepted) Py_RETURN_NONE;
    }

    if (fabs(cimag(lam)) <= 1e-12 * (1.0 + zabs(lam))) {
        double n1 = 0.0, n2 = 0.0;
        for (i = 0; i < n; i++) {
            n1 += creal(v[i]) * creal(v[i]);
            n2 += cimag(v[i]) * cimag(v[i]);
        }
        if (n1 >= n2) {
            nv = sqrt(n1);
            for (i = 0; i < n; i++) vr[i] = creal(v[i]) / nv;
        } else {
            nv = sqrt(n2);
            for (i = 0; i < n; i++) vr[i] = cimag(v[i]) / nv;
        }
        if (nv > 0.0 && residual_ok_real(a, n, creal(lam), vr, atol))
            return make_result(CX(creal(lam) / scale, 0.0), NULL, n, 1, vr);
    }

    return make_result(zdiv(lam, CX(scale, 0.0)), v, n, 0, NULL);
}

static PyMethodDef methods[] = {
    {"dominant", dominant, METH_O, "dominant eigenpair or None"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigen_fast", NULL, -1, methods,
    NULL, NULL, NULL, NULL
};

PyMODINIT_FUNC PyInit__eigen_fast(void)
{
    PyObject *m = PyModule_Create(&moduledef);
    if (!m) return NULL;
    import_array();
    return m;
}

