        J=np.eye(n,k=1)+np.random.choice([0.,2.])*np.eye(n); Q=np.linalg.qr(np.random.normal(size=(n,n)))[0]; A=Q@J@Q.T
    else: A=np.eye(n,k=-1)*np.random.choice([1.,3.])+np.random.normal()*np.eye(n)
    o,isfb=chk(A,f"rand{typ}",verbose=False); tot+=1
